import type { EngineInterface as Api, Register } from 'claude-code'
import { buildWrapper, isDelegation, paneLabel, runDirPath, scriptPath, stubFor, type ClosePolicy } from './wrap.ts'
import { runPane } from './runpane.tsx'
import { callEnded, settleRun, text, trackRun } from './runstate.ts'

const FOREGROUND_MAX_MS = 600000

const closePolicy = (v: unknown): ClosePolicy => (v === 'success' || v === 'never' ? v : 'always')

const SEND = 'copy it to a folder they can open (your scratchpad or the working directory) and send it to them as a file to render.'

// For the model, where nothing in this session draws mod panes: how to show the run to the user.
// A foreground call has ended, so its page exists or never will; a background one names its page
// in its report (a "run page:" line) when it ends. Elsewhere the report's line is enough.
// A call cut off by its timeout has returned for good while its run goes on (in a pane):
// no report will name the page, so the note names where the poller writes it. A bare run (no
// host file: outside herdr, no pane to be had) ended with the call and gets no page.
type CallEnd = 'done' | 'background' | 'interrupted'
async function pageNote($: Api, id: string, end: CallEnd, dir: string): Promise<string | undefined> {
  const page = end === 'done' ? await settleRun($, id) : undefined // ends the run here even if it left no exit
  if ((await $.session.surfaces()).length > 0) return undefined
  if (end === 'background') return `codex-herdr-pane: nothing in this session draws mod panes. If this delegation's report ends with a "run page:" line, show the run to the user: ${SEND}`
  if (end === 'interrupted') {
    const host = (await text($, `${dir}/host`))?.trim()
    if (host !== 'herdr' && host !== 'claude') return undefined
    return `codex-herdr-pane: nothing in this session draws mod panes. This call timed out while the delegation runs on, so no report will follow. Once it ends, its page is ${dir}/run.html (the user can also type /codex-runs). When that file exists, show the run to the user: ${SEND}`
  }
  return page ? `codex-herdr-pane: nothing in this session draws mod panes, so show the run to the user through its page, ${page}: ${SEND}` : undefined
}

export const register: Register = (on, options) => {
  // layout right/down is a fixed split of Claude's pane; anything else tiles. `direction` is the
  // legacy option, honoured only when layout is auto or not configured.
  const layout = typeof options.layout === 'string' && options.layout !== 'auto' ? options.layout : undefined
  const fixedDown = layout === 'down' || (layout === undefined && options.direction === 'down')
  const fixed = layout === 'right' || fixedDown
  const direction = fixedDown ? 'down' : 'right'
  const maxPanes = typeof options.maxPanes === 'number' && options.maxPanes >= 1 ? Math.floor(options.maxPanes) : 6
  const closePane = closePolicy(options.closePane)
  const closeDelay = typeof options.closeDelay === 'number' ? options.closeDelay : 3
  const tailLines = typeof options.tailLines === 'number' ? options.tailLines : 200
  const maxReturnLines = typeof options.maxReturnLines === 'number' && options.maxReturnLines >= 0 ? Math.floor(options.maxReturnLines) : 60
  const viewer = options.viewer === 'plain' ? 'plain' : 'textual'
  const leanProfile = options.leanProfile !== false
  const leanProfileName = typeof options.leanProfileName === 'string' && options.leanProfileName.trim() ? options.leanProfileName.trim() : 'lean'
  const runsDir = typeof options.ccxRunsDir === 'string' && options.ccxRunsDir.trim() ? options.ccxRunsDir.trim() : undefined
  // auto: outside herdr, a run is followed in a Claude Code pane (runpane.tsx); off: run as asked.
  // Every run is followed to its end either way, for its page (run.html).
  const claudePane = options.claudePane === 'auto'
  runPane(on, { closePane, closeDelay })
  let n = 0

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (!isDelegation(e.command)) return next(e)
    n += 1
    const id = `${Date.now().toString(36)}${n}`
    $.ui.toast(claudePane ? 'Delegation: opening a pane' : 'Delegation: opening a herdr pane')
    let tmpdir: string | undefined, home: string | undefined
    try { tmpdir = await $.env.get('TMPDIR') } catch { /* /tmp */ }
    try { home = await $.env.get('HOME') } catch { /* not followed */ }
    const runDir = runDirPath(home, id)
    const script = buildWrapper(e.command, {
      direction, layout: fixed ? 'fixed' : 'tile', maxPanes, closePane, closeDelay, tailLines, maxReturnLines, viewer, leanProfile, leanProfileName, runsDir, root: $.plugin.root, id,
      claudePane, runDir,
    })
    // Followed by what the script writes in $dir/host: claude (a Claude Code pane), herdr, or none (bare)
    if (runDir) await trackRun($, { id, dir: runDir, label: paneLabel(e.command) }).catch(() => {})
    // The script goes to a file written here, so the call the harness shows (and quotes in the
    // notice of a background call) is the two-line stub. If the write fails or the file is not
    // there, the call carries the whole script, as before 0.7.0.
    let command = script
    try {
      const path = scriptPath(tmpdir, id)
      await $.fs.write(path, script)
      if (await $.fs.exists(path)) command = stubFor(path)
    } catch { /* keep the inline script */ }
    // A foreground call may wait on a long Codex run, so one with no timeout gets the
    // longest wait the Bash tool allows. A timeout the caller set is kept, so a call meant
    // to give up early still does; the pane keeps running either way.
    const timeout = e.run_in_background || typeof e.timeout === 'number' ? e.timeout : FOREGROUND_MAX_MS
    const ran = await next({ ...e, command, timeout })
    if (!runDir) return ran
    // Never throws: the .catch below would run the delegation a second time
    try {
      await callEnded($, id, ran.result === undefined)
      if (ran.result === undefined) return ran
      const interrupted = Boolean((ran.result as { interrupted?: boolean }).interrupted)
      const end: CallEnd = e.run_in_background ? 'background' : interrupted ? 'interrupted' : 'done'
      const note = await pageNote($, id, end, runDir)
      return note ? { ...ran, context: [...(ran.context ?? []), note] } : ran
    } catch {
      return ran
    }
  }).catch((_$, e, next) => next(e)) // a failure here must never block the delegation
}

files.hooks/wrap.ts:
// Pure helpers for the codex-herdr-pane mod: build the shell text that runs a
// delegation (see tools.ts) in a herdr pane.

import { MARKER, TOOLS, isStandalone, redirectsStdout, toolFor, type DelegationTool } from './tools.ts'

export { MARKER, isCodexDelegation, isDelegation, paneLabel } from './tools.ts'
import { paneLabel } from './tools.ts'
import { SHIM } from './shim.ts'
import { NL_FN } from './mdpipe.ts'
import { paneScript } from './panescript.ts'
import { splitSection, unregisterCmd } from './layout.ts'

export type ClosePolicy = 'always' | 'success' | 'never'

export type WrapOptions = {
  direction: 'right' | 'down' // the fixed split used when layout is 'fixed'
  layout: 'tile' | 'fixed' // tile: a grid beside Claude (layout.ts); fixed: always split Claude's pane in `direction`
  maxPanes: number // tile only: live delegation panes allowed before a run goes without a pane
  closePane: ClosePolicy
  closeDelay: number
  tailLines: number
  maxReturnLines?: number // the most lines of each returned section (answer, log tail, rest of command); 0 or unset: no cap
  viewer: 'textual' | 'plain'
  root: string // the plugin's folder: holds viewer/codex_view.py, clean.awk and codex.jq
  leanProfile: boolean // add -p <leanProfileName> to codex exec when that profile file exists
  leanProfileName: string
  id: string
  runsDir?: string // ccx's run-log directory; the pane's CCX_RUNS_DIR overrides it
  // Outside herdr, run the delegation headless into runDir instead of running it bare, so the
  // Claude Code pane (runpane.tsx) can follow it.
  claudePane?: boolean
  // The run directory (runDirPath), named by the id so the hook can follow the run to its end
  runDir?: string
}

// The hook writes the whole wrapper to <TMPDIR>/<SCRIPT_PREFIX><id>.sh itself and the Bash call
// becomes this stub, so the harness's notice of a background call quotes two lines, not the script.
export const SCRIPT_PREFIX = 'codex-herdr-run.'
export const scriptPath = (tmpdir: string | undefined, id: string): string => {
  const dir = tmpdir && tmpdir.startsWith('/') ? tmpdir.replace(/\/+$/, '') : '/tmp'
  return `${dir || ''}/${SCRIPT_PREFIX}${id.replace(/[^A-Za-z0-9]/g, '')}.sh`
}
// Where run directories live: under the user's own cache, never a shared /tmp, so no other user
// can make one of these paths before the run does (the hook reads and writes there by name).
export const runsRoot = (home: string): string => `${home.replace(/\/+$/, '')}/.cache/codex-herdr-pane/runs`
// A run's directory, named by the id so the hook knows it before the script runs; undefined
// without a usable HOME (then the run gets a mktemp directory and is not followed)
export const runDirPath = (home: string | undefined, id: string): string | undefined =>
  home && home.startsWith('/') ? `${runsRoot(home)}/${id.replace(/[^A-Za-z0-9]/g, '')}` : undefined
const shq = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`
export const stubFor = (path: string): string => `${MARKER}\nexec bash ${shq(path)}`

const word =(s: string) => s.replace(/[^A-Za-z0-9 _.:\/=+-]/g, '')

function heredoc(path: string, delim: string, body: readonly string[]): string[] {
  return [`cat > "${path}" <<'${delim}'`, ...body, delim]
}

// What the Bash call returns to Claude. Codex: the status, then the answer when
// there is one, else the tail of the cleaned log. ccx: what an unwrapped run
// returns, its own stdout (status line and result) and its stderr.
// A chained call (isStandalone in tools.ts) adds, for codex, a header and the whole
// original command's captured stdout, then its stderr; for ccx that capture already
// is the status line and result, so it is returned as is.
//
// Every section but the status line goes through cap_file: the first __M lines, then one
// "... N more lines in <file>" line naming the file that holds them. __M=0 returns it whole,
// and a section of at most __M lines is returned byte for byte as `cat` and nl_if_open did.
const CAP_FN = 'cap_file() { local n; n=$(awk \'END{print NR}\' "$1"); if [ "$__M" -gt 0 ] && [ "$n" -gt "$__M" ]; then head -n "$__M" "$1"; echo "... $((n - __M)) more lines in ${2:-$1}"; else cat "$1"; nl_if_open "$1"; fi; }'
// cap_tail is cap_file for a log's end, where the error is: the LAST __M lines, led by a line naming how many earlier ones $2 (the whole log) holds.
const CAP_TAIL_FN = 'cap_tail() { local n t; n=$(awk \'END{print NR}\' "$1"); if [ "$__M" -gt 0 ] && [ "$n" -gt "$__M" ]; then t=$(awk \'END{print NR}\' "${2:-$1}"); echo "... $((t - __M)) earlier lines in ${2:-$1}"; tail -n "$__M" "$1"; else cat "$1"; fi; nl_if_open "$1"; }'

// The run's page (run.html), named last in the report only once it exists. The hook writes it
// moments after the run ends, so a followed run (one with a host file) waits for it up to
// CODEX_HERDR_PAGE_WAIT tenths of a second (30).
const PAGE_LINE = [
  'if [ -s "$__D/host" ]; then __w=0; while [ ! -f "$__D/run.html" ] && [ "$__w" -lt "${CODEX_HERDR_PAGE_WAIT:-30}" ]; do sleep 0.1; __w=$((__w+1)); done; fi',
  '[ -f "$__D/run.html" ] && echo "run page: $__D/run.html"',
]

function report(o: WrapOptions, tool: DelegationTool, chained: boolean): string[] {
  const cap = Math.max(0, Math.floor(o.maxReturnLines ?? 0)) || 0
  const head = [NL_FN, CAP_FN, CAP_TAIL_FN, `__M=${cap}`]
  if (tool.filter === 'ccx') {
    return [...head, '__X=$(cat "$__D/exit")', 'cap_file "$__D/out.txt"', 'cat "$__D/err.log" >&2; nl_if_open "$__D/err.log" >&2', ...PAGE_LINE]
  }
  const tail = Math.max(1, Math.floor(o.tailLines))
  const who = chained ? 'command' : 'codex'
  return [
    ...head,
    '__X=$(cat "$__D/exit")',
    '__T=$(( $(cat "$__D/end" 2>/dev/null || date +%s) - $(cat "$__D/start" 2>/dev/null || date +%s) ))',
    '__K=$(cat "$__D/usage" 2>/dev/null)',
    `echo "${who} exited $__X after \${__T}s\${__K:+, $__K}; raw log $__D/raw.log, answer file $__D/last.md"`,
    // on failure the end of clean.log: its last __M lines, led by a pointer to the earlier ones in clean.log
    'if [ "$__X" = 0 ] && [ -s "$__D/last.md" ]; then cap_file "$__D/last.md"; else tail -n ' + tail + ' "$__D/clean.log" > "$__D/tail.out"; cap_tail "$__D/tail.out" "$__D/clean.log"; fi',
    ...(chained ? [
      // rest.out / rest.err: orig.out / orig.err with the pane's noise rules applied (panescript.ts)
      'if [ -s "$__D/rest.out" ] || [ -s "$__D/rest.err" ]; then echo "--- output of the rest of the command ---"; cap_file "$__D/rest.out"; cap_file "$__D/rest.err" >&2; fi',
    ] : []),
    ...PAGE_LINE,
  ]
}

function closeSection(o: WrapOptions): string[] {
  const delay = Math.max(0, Math.floor(o.closeDelay))
  const when = o.closePane === 'always' ? 'true' : o.closePane === 'success' ? '[ "$__X" = 0 ]' : 'false'
  return [
    `if ${when}; then ( sleep ${delay}; herdr pane close "$__P" >/dev/null 2>&1; ${unregisterCmd(o)} ) >/dev/null 2>&1 & fi`,
    'exit "$__X"',
  ]
}

// Old leftovers in TMPDIR, removed in the background at each run after CODEX_HERDR_KEEP_DAYS days
// (7): a script the hook wrote for a call that never ran (a denied call), run directories and
// ccx claims. Days, not hours, for the scripts too: another session's call can wait a long time
// at its approval prompt, and its script must still be there when it is approved.
const SWEEP = '( T="${TMPDIR:-/tmp}"; K="${CODEX_HERDR_KEEP_DAYS:-7}"; '
  + 'find "$T" -maxdepth 1 -type f -name \'' + SCRIPT_PREFIX + '*.sh\' -mtime +"$K" -delete; '
  + 'find "$T" -maxdepth 1 -type d -name \'codex-herdr.*\' -mtime +"$K" -exec rm -rf {} +; '
  + 'find "$T/codex-herdr-ccx-claims-$(id -u)" -mindepth 1 -maxdepth 1 -type d -name \'*.jsonl\' -mtime +"$K" -exec rm -rf {} +; '
  + 'find "$HOME/.cache/codex-herdr-pane/runs" -mindepth 1 -maxdepth 1 -type d -mtime +"$K" -exec rm -rf {} +; '
  + ') >/dev/null 2>&1 &'

export function buildWrapper(command: string, o: WrapOptions): string {
  const tool = toolFor(command) ?? TOOLS[0]!
  const chained = !isStandalone(command)
  const orig = `__CODEX_HERDR_ORIG_${o.id}__`
  const shim = `__CODEX_HERDR_SHIM_${o.id}__`
  const pane = `__CODEX_HERDR_PANE_${o.id}__`
  const claude = Boolean(o.claudePane && o.runDir)
  const mktemp = '__D=$(mktemp -d "${TMPDIR:-/tmp}/codex-herdr.XXXXXX") || exit 1'
  return [
    MARKER,
    // mkdir without -p for the run itself: a path already there is never reused (mktemp instead,
    // and the hook, finding no host file there, does not follow it)
    o.runDir
      ? `__R=${shq(o.runDir.replace(/\/[^/]*$/, ''))}; __D=${shq(o.runDir)}; { mkdir -p "$__R" && chmod 700 "$__R" && mkdir -m 700 "$__D"; } 2>/dev/null || { ${mktemp}; }`
      : mktemp,
    // A script the hook wrote (see stubFor) moves into the run directory, so it is kept with the logs
    'case "$0" in */' + SCRIPT_PREFIX + '*.sh) mv "$0" "$__D/wrapper.sh" 2>/dev/null;; esac',
    SWEEP,
    ...heredoc('$__D/orig.sh', orig, [command]),
    ...(claude ? [
      ...(tool.shim ? heredoc('$__D/shim.sh', shim, SHIM) : []),
      ...heredoc('$__D/pane.sh', pane, paneScript(o, tool, chained, !chained && !redirectsStdout(command))),
      `printf '%s' ${JSON.stringify(word(paneLabel(command)))} > "$__D/label"`,
      // Outside herdr, or without the binary: the same run with no viewer, which the Claude Code
      // pane follows (host tells it which runs are its own), then the same report.
      'if [ "${HERDR_ENV:-}" != 1 ] || ! command -v herdr >/dev/null 2>&1; then',
      '  echo claude > "$__D/host"',
      `  bash "$__D/pane.sh" "$__D" ${shq(o.root)} none ${chained ? 1 : 0} </dev/null >/dev/null 2>&1`,
      ...report(o, tool, chained).map((l) => '  ' + l),
      '  exit "$__X"',
      'fi',
    ] : [
      // Outside herdr, or without the binary, run the command exactly as asked.
      'if [ "${HERDR_ENV:-}" != 1 ] || ! command -v herdr >/dev/null 2>&1; then exec bash "$__D/orig.sh"; fi',
      ...(tool.shim ? heredoc('$__D/shim.sh', shim, SHIM) : []),
      ...heredoc('$__D/pane.sh', pane, paneScript(o, tool, chained, !chained && !redirectsStdout(command))),
      `printf '%s' ${JSON.stringify(word(paneLabel(command)))} > "$__D/label"`,
    ]),
    ...splitSection(o),
    'if [ -z "$__P" ]; then exec bash "$__D/orig.sh"; fi',
    // Only now is there a herdr pane that will end the run: the hook follows it to its end, for the page
    'echo herdr > "$__D/host"',
    `herdr pane run "$__P" bash "$__D/pane.sh" "$__D" ${shq(o.root)} ${o.viewer} ${chained ? 1 : 0} >/dev/null`,
    // After the run, so the shell's own title for the typed command does not replace it
    'herdr pane rename "$__P" "$(cat "$__D/label")" >/dev/null 2>&1 || true',
    'while [ ! -f "$__D/exit" ]; do',
    `  herdr pane get "$__P" >/dev/null 2>&1 || { ${unregisterCmd(o)}; echo "the herdr pane $__P was closed before ${tool.name} finished (log: $__D/raw.log)"; date +%s > "$__D/end"; echo 130 > "$__D/exit"; exit 130; }`,
    '  sleep 1',
    'done',
    ...report(o, tool, chained),
    ...closeSection(o),
  ].join('\n')
}

files.hooks/runpane.tsx:
// The Claude Code side of a delegation run: outside herdr (claudePane auto) a run is headless and
// is drawn here, in a pane of Claude Code's own (one per run; several are tabs). runstate.ts
// follows every run to its end and writes its page; runview.tsx draws the pane. /codex-runs shows
// the newest run: in its pane where a surface draws one, else as text in the chat.

import type { EngineInterface as Api, On } from 'claude-code'
import { summarizeRun } from './livedoc.ts'
import { loadParts, renderPane } from './runview.tsx'
import { PANE_PREFIX, allRuns, paneId, poll, runStatus, setPaneOptions, type PaneOptions } from './runstate.ts'

export { paneId, PANE_PREFIX } from './runstate.ts'

// /codex-runs: the newest run in its pane, opened as the person asked (placed at any width)
async function showLatest($: Api) {
  const latest = Object.values(await allRuns($)).filter((r) => r.host !== 'pending').sort((a, b) => b.registered - a.registered)[0]
  if (!latest) return { text: 'No delegation run is followed in this session yet.' }
  // a live herdr run is drawn by its herdr pane; this side reads it only once it ends
  if (latest.host === 'herdr' && latest.exit === undefined) return { text: `${latest.label} is running in its herdr pane.` }
  const opened = await $.ui.open({ id: paneId(latest.id), title: latest.label.slice(0, 60), focus: true })
  if (opened.isPlaced) return { text: `Showing ${latest.label}.` }
  // No surface draws the pane (a cloud session viewed in the app, a -p run): the run goes in the chat
  const { parts } = await loadParts($, latest)
  const head = `${latest.label}: ${runStatus(latest, await $.clock.now())}`
  const page = latest.page ? `\n\nAs a page with collapsible tool results: ${latest.page}` : ''
  return { text: summarizeRun(parts, head, latest.answer, `${latest.dir}/clean.md`) + page }
}

export function runPane(on: On, o: PaneOptions) {
  setPaneOptions(o)
  // A reload keeps $.state but not the timer: follow the runs still live
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'codex-runs', description: 'Show the newest Codex or ccx delegation run in a pane' })
    if (Object.values(await allRuns($)).some((r) => r.exit === undefined)) poll($)
    return next(e)
  })

  on('command.run', { command: 'codex-runs' }, async ($) => showLatest($))

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (!e.requestId.startsWith(PANE_PREFIX)) return next(e)
    const ui = $.ui.resolve(e)
    const r = (await allRuns($))[e.requestId.slice(PANE_PREFIX.length)]
    if (!r) return <ui.Text dimColor>This run is no longer followed.</ui.Text>
    return renderPane(ui, $, r, await $.clock.now())
  })
}

files.hooks/runstate.ts:
// Follows each delegation's run directory (wrap.ts) from the moment the hook sees the call to the
// run's end, then writes run.html (runhtml.ts). The state holds what the pane needs to know, not
// the log: the pane reads clean.md when it draws (runview.tsx).
//
// One step per run at a time (stepRun): the poll timer and the tool.call hook's settleRun both go
// through it, so a run is finished, its page written and its pane closed once.

import { atom, read, update } from 'claude-code'
import type { EngineInterface as Api } from 'claude-code'
import type { RunView } from '../types'
import { parseRun } from './livedoc.ts'
import { runPage } from './runhtml.ts'
import type { ClosePolicy } from './wrap.ts'

export const PANE_PREFIX = 'codex-run-'
export const paneId = (id: string) => PANE_PREFIX + id
const POLL_MS = 700
const NO_HOST_MS = 30000 // after the call returned with no host file: it ran bare, or never ran
const STALL_MS = 30 * 60000 // a run whose log has not grown for this long is given up on
const KEEP_DONE = 20
const MAX_ANSWER = 20000

const runs = atom({ plugin: 'codex-herdr-pane', key: 'runs' } as const, {})

// Every followed run, by id (the state is read here only: the scan needs the atom in this module)
export async function allRuns($: Api): Promise<Record<string, RunView>> {
  return read($, runs)
}

export type PaneOptions = { closePane: ClosePolicy; closeDelay: number }
let opts: PaneOptions = { closePane: 'always', closeDelay: 3 }
export function setPaneOptions(o: PaneOptions) { opts = o }

let timer: { cancel: () => void } | undefined
let ticking = false
const inflight = new Map<string, Promise<void>>()

export const clock = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000)), m = Math.floor(s / 60)
  return m ? `${m}m${String(s % 60).padStart(2, '0')}s` : `${s}s`
}

export function runStatus(r: RunView, now: number): string {
  const took = clock((r.ended ?? now) - (r.started ?? r.registered))
  if (r.exit === undefined) return `running for ${took}`
  if (r.exit === 'gone') return `ended without an exit status after ${took}`
  return `${r.exit === '0' ? 'finished' : `failed with exit ${r.exit}`} in ${took}${r.usage ? ` · ${r.usage}` : ''}`
}

export async function patch($: Api, id: string, fn: (r: RunView) => RunView | undefined) {
  await update($, runs, (all) => {
    const cur = all[id]
    if (!cur) return all
    const next = fn(cur)
    const { [id]: _gone, ...rest } = all
    return next ? { ...rest, [id]: next } : rest
  })
}

export async function text($: Api, path: string) {
  try { return await $.fs.read(path) } catch { return undefined }
}

async function num($: Api, path: string) {
  return Number((await text($, path))?.trim()) || 0
}

// The host the wrapper wrote: claude opens this run's pane, herdr is only followed to its end
async function resolveHost($: Api, r: RunView, now: number) {
  const host = (await text($, `${r.dir}/host`))?.trim()
  if (host !== 'claude' && host !== 'herdr') {
    if (r.callEnded !== undefined && now - r.callEnded > NO_HOST_MS) await patch($, r.id, () => undefined)
    return
  }
  const label = (await text($, `${r.dir}/label`))?.trim() || r.label
  await patch($, r.id, (c) => ({ ...c, host, label }))
  if (host !== 'claude') return
  // Opened unasked, a surface may hold it undrawn (a narrow one); /codex-runs opens it as asked
  const opened = await $.ui.open({ id: paneId(r.id), title: label.slice(0, 60) })
  if (!opened.isPlaced) $.ui.log(`codex-herdr-pane: the run's pane waits undrawn (${opened.reason}); /codex-runs shows it`)
}

// The page, written unless run.html is already there as a link (only this user writes in the
// run directory, so that is never expected; it is refused all the same)
async function writePage($: Api, r: RunView, now: number): Promise<string | undefined> {
  const page = `${r.dir}/run.html`
  try {
    if (await $.fs.exists(page) && (await $.fs.stat(page)).isLink) return undefined
    const md = (await text($, `${r.dir}/clean.md`)) ?? ''
    await $.fs.write(page, runPage({
      label: r.label, status: runStatus(r, now), ok: r.exit === '0', parts: parseRun(md, true), answer: r.answer, logPath: `${r.dir}/clean.md`,
    }))
    return page
  } catch (err) {
    $.ui.log(`codex-herdr-pane: run page not written: ${String(err)}`, { to: 'debug' })
    return undefined
  }
}

// Ends a run: its exit (or 'gone'), usage, answer and times, then its page; a claude pane closes
// per closePane
async function finish($: Api, r: RunView, exit: string, now: number) {
  const usage = (await text($, `${r.dir}/usage`))?.trim() || undefined
  const answer = ((await text($, `${r.dir}/last.md`)) ?? '').trim().slice(0, MAX_ANSWER)
  const start = await num($, `${r.dir}/start`)
  const end = await num($, `${r.dir}/end`) || Math.floor(now / 1000)
  const done: RunView = { ...r, exit, usage, answer, started: start * 1000 || r.started, ended: end * 1000, tab: exit === '0' && answer ? 'answer' : 'live' }
  const page = await writePage($, done, now)
  await patch($, r.id, (c) => ({ ...c, exit, usage, answer, started: done.started, ended: done.ended, page, tab: c.tab === 'live' && done.tab === 'answer' ? 'answer' : c.tab }))
  if (r.host !== 'claude') return
  const close = opts.closePane === 'always' || (opts.closePane === 'success' && exit === '0')
  if (close) $.clock.after(Math.max(0, opts.closeDelay) * 1000, () => void $.ui.close({ id: paneId(r.id) }).catch(() => {}))
}

async function step($: Api, r: RunView, now: number) {
  if (r.exit !== undefined) return
  if (r.host === 'pending') return resolveHost($, r, now)
  const exit = (await text($, `${r.dir}/exit`))?.trim()
  if (exit) return finish($, r, exit, now)
  let size = r.size
  try { size = (await $.fs.stat(`${r.dir}/clean.md`)).size } catch { /* not there yet */ }
  if (size !== r.size) {
    const start = await num($, `${r.dir}/start`)
    await patch($, r.id, (c) => ({ ...c, size, lastChange: now, started: start * 1000 || c.started }))
  } else if (now - r.lastChange > STALL_MS) {
    await finish($, r, 'gone', now)
  }
}

// One piece of work at a time per key: a second caller waits for the one in flight, then runs its
// own (which reads the run as it is by then)
export function serial(key: string, work: () => Promise<void>): Promise<void> {
  const before = inflight.get(key) ?? Promise.resolve()
  const p: Promise<void> = before.catch(() => {}).then(work).finally(() => { if (inflight.get(key) === p) inflight.delete(key) })
  inflight.set(key, p)
  return p
}

async function exclusive($: Api, id: string, work: (r: RunView, now: number) => Promise<void>): Promise<void> {
  return serial(id, async () => {
    const r = (await read($, runs))[id]
    if (r) await work(r, await $.clock.now())
  })
}

export function stepRun($: Api, id: string): Promise<void> {
  return exclusive($, id, (r, now) => step($, r, now))
}

async function tick($: Api) {
  if (ticking) return
  ticking = true
  try {
    const live = Object.values(await read($, runs)).filter((r) => r.exit === undefined)
    if (live.length === 0) {
      timer?.cancel(); timer = undefined
      // a run registered while the state was read found the old timer and started none: start one
      if (Object.values(await read($, runs)).some((r) => r.exit === undefined)) poll($)
      return
    }
    for (const r of live) await stepRun($, r.id)
  } finally { ticking = false }
}

export function poll($: Api) {
  timer ??= $.clock.every(POLL_MS, () => void tick($).catch((err) => $.ui.log(`codex-herdr-pane: ${String(err)}`, { to: 'debug' })))
}

// Called by the tool.call hook for each delegation it wraps, before the call (and its approval)
export async function trackRun($: Api, run: { id: string; dir: string; label: string }) {
  const now = await $.clock.now()
  const view: RunView = { ...run, host: 'pending', registered: now, size: 0, lastChange: now, answer: '', tab: 'live', open: {} }
  // Every delegation is followed, so only the newest KEEP_DONE finished runs are kept
  await update($, runs, (all) => {
    const done = Object.values(all).filter((r) => r.exit !== undefined).sort((a, b) => b.registered - a.registered)
    const drop = new Set(done.slice(KEEP_DONE).map((r) => r.id))
    return { ...Object.fromEntries(Object.entries(all).filter(([id]) => !drop.has(id))), [run.id]: view }
  })
  poll($)
}

// Called once the Bash call returned: a refused call is dropped; otherwise the no-host clock starts
export async function callEnded($: Api, id: string, refused: boolean) {
  const now = await $.clock.now()
  await patch($, id, (c) => (refused ? undefined : { ...c, callEnded: now }))
}

// For a foreground call that returned: its wrapper has ended, so the run has ended. Reads its end
// now (or gives it up as 'gone' when it left none), so the page exists before the model reads the
// result. The page's path, or undefined (a bare run, or one whose page could not be written).
export async function settleRun($: Api, id: string): Promise<string | undefined> {
  for (let i = 0; i < 3; i++) {
    const r = (await read($, runs))[id]
    if (!r) return undefined
    if (r.exit !== undefined) return r.page
    if (i < 2) await stepRun($, id)
    else await exclusive($, id, (c, now) => (c.exit === undefined && c.host !== 'pending' ? finish($, c, 'gone', now) : Promise.resolve()))
  }
  return (await read($, runs))[id]?.page
}

