import { NL_FN, mdFunctions } from './mdpipe.ts'

// The shell function that stands in for `codex` inside the pane. Pure text.
//
// For exec/e it adds, each only when the call does not already say so:
//   --output-last-message  the answer as a clean file
//   -p <profile>           the lean profile, only when ~/.codex/<profile>.config.toml
//                          exists (codex review has no profile flag and is untouched)
//   --json                 so the usage event can be read (codex.jq renders it)
// A standalone review (it has no --json) writes its final message to stdout and its progress
// to stderr: stdout goes to the answer file, so the call returns the verdict as exec does and
// the log holds the progress once. A chained review keeps stdout for the caller, and so does a
// review whose stdout the caller redirected: the wrapper sets __CODEX_REVIEW_LAST only for a
// standalone call with no stdout redirect of its own (redirectsStdout, tools.ts).
// CHAINED calls (see isStandalone in tools.ts) set __CODEX_CHAIN: the command's stdout
// is the caller's, so for exec the shim sends codex's JSONL only to the pane
// (raw.log, then codex.jq and clean.awk into clean.log) and prints the answer file to
// its own stdout, which is what a plain `codex exec` prints. A call that names its own -o
// file takes the same route (issue 225: its stdout used to stay JSONL and reached the pane
// raw): codex writes the caller's file exactly as asked, and the shim copies it to the answer
// file, so the report, the Answer tab and the chained stdout all get the answer. Every other
// call with its own -o gets that copy too. Only a chained call that asks for --json itself
// keeps codex's stdout as it is.
// The same stream also feeds clean.md through mdcodex (mdpipe.ts).
// __CODEX_PROFILE is empty when the option is off. A function, so no quoting of the
// user's text.
export const SHIM = [
  ...mdFunctions('$__CODEX_ROOT'),
  NL_FN,
  // The caller's own -o file becomes the answer file too (a relative path is read from the
  // directory codex was started in, as codex wrote it)
  'own_to_last() { [ -n "$own" ] && [ "$own" != "$__CODEX_LAST" ] && [ -f "$own" ] && cp "$own" "$__CODEX_LAST" 2>/dev/null; return 0; }',
  'codex() {',
  '  local a sub="$1" pre=() has_o="" has_p="" has_j="" own="" want=""',
  '  if [ -n "${__CODEX_LAST:-}" ] && { [ "$1" = exec ] || [ "$1" = e ]; }; then',
  '    shift',
  // own: the caller's -o file, in each spelling clap accepts (-o F, -oF, -o=F, --output-last-message[=]F)
  '    for a in "$@"; do',
  '      if [ -n "$want" ]; then own="$a"; want=""; continue; fi',
  '      case "$a" in',
  '      --) break;;',
  '      -o|--output-last-message) has_o=1; want=1;;',
  '      --output-last-message=*) has_o=1; own="${a#*=}";;',
  '      -o?*) has_o=1; own="${a#-o}"; own="${own#=}";;',
  '      -p|--profile|--profile=*) has_p=1;;',
  '      --json) has_j=1;;',
  '    esac; done',
  '    [ -z "$has_o" ] && pre+=(--output-last-message "$__CODEX_LAST")',
  '    if [ -z "$has_p" ] && [ -n "${__CODEX_PROFILE:-}" ] && [ -f "$HOME/.codex/${__CODEX_PROFILE}.config.toml" ]; then pre+=(-p "$__CODEX_PROFILE"); fi',
  '    [ -z "$has_j" ] && pre+=(--json)',
  '    local rc',
  '    if [ -n "${__CODEX_CHAIN:-}" ] && [ -z "$has_j" ]; then',
  '      : > "$__CODEX_LAST"',
  '      command codex "$sub" "${pre[@]}" "$@" | tee -a "$__CODEX_D/raw.log" >(mdcodex >> "$__CODEX_D/clean.md") | jq --unbuffered -R -r -f "$__CODEX_ROOT/viewer/codex.jq" 2>/dev/null \\',
  '        | awk -v seen="${MCP_SEEN_LOG:-}" -f "$__CODEX_ROOT/viewer/clean.awk" >> "$__CODEX_D/clean.log"',
  '      rc="${PIPESTATUS[0]}"; own_to_last; cat "$__CODEX_LAST" 2>/dev/null; nl_if_open "$__CODEX_LAST"; return "$rc"',
  '    fi',
  '    command codex "$sub" "${pre[@]}" "$@"; rc=$?',
  '    own_to_last; return "$rc"',
  '  elif [ -n "${__CODEX_LAST:-}" ] && [ -n "${__CODEX_REVIEW_LAST:-}" ] && [ "$1" = review ]; then',
  '    command codex "$@" > "$__CODEX_LAST"',
  '  else',
  '    command codex "$@"',
  '  fi',
  '}',
]

files.hooks/mdpipe.ts:
// The Markdown half of the run log, and the noise rules for the text returned to Claude:
// shell text shared by the pane script and the shim so each pipeline is written once.
// `root` is a shell expression for the plugin folder ($ROOT in the pane, $__CODEX_ROOT in
// the shim).
//
// mdcodex     raw Codex stream on stdin -> Markdown on stdout. The noise rules run first
//             (on the raw lines, which are JSONL or noise), because once a noise line is
//             inside a fence clean.awk's line-start patterns no longer match it. joinfence.awk
//             then runs neighbouring text fences together (codex review is plain text, one
//             fence per line otherwise).
// mdrest      the rest of a chained command's output -> Markdown: the same clean.awk, then
//             rest.awk (drops a copy of the final answer), then md.jq's mdline.
// restfilter  the same rules as plain text (what the Bash call returns, and the rest of a chained
//             command in clean.log); $1 is the
//             "MCP note already made" file for that text.
// MCP_SEEN_MD / MCP_SEEN_LOG are set by the pane script in a chained call only, so the MCP
// note is made once per run directory instead of once per process.
export function mdFunctions(root: string): string[] {
  const jq = (mode: string) => `jq --unbuffered -R -r --arg mode ${mode} -f "${root}/viewer/codex.jq" 2>/dev/null`
  const clean = (seen: string, review = '') => `awk -v seen="${seen}"${review} -f "${root}/viewer/clean.awk"`
  const rest = `awk -v last="\${__CODEX_LAST:-}" -f "${root}/viewer/rest.awk"`
  return [
    `mdcodex() { ${clean('${MCP_SEEN_MD:-}', ' -v review=1')} | ${jq('md')} | awk -f "${root}/viewer/joinfence.awk"; }`,
    `mdrest() { ${clean('${MCP_SEEN_MD:-}')} | ${rest} | ${jq('mdraw')}; }`,
    `restfilter() { ${clean('$1')} | ${rest} | jq --unbuffered -R -r --arg mode rest -f "${root}/viewer/codex.jq" 2>/dev/null; }`,
  ]
}

// Prints a newline when the file's last byte is not one (so a report never ends mid-line and
// never gets a blank line it did not need). $(tail -c1) is empty exactly when the file is
// empty or ends in a newline.
export const NL_FN = 'nl_if_open() { [ -n "$(tail -c1 "$1" 2>/dev/null)" ] && echo; return 0; }'

files.hooks/panescript.ts:
// The script that runs inside the herdr pane (see wrap.ts for the Bash-call side).

import type { DelegationTool } from './tools.ts'
import type { WrapOptions } from './wrap.ts'
import { mdFunctions } from './mdpipe.ts'

// The Textual versions the viewer was tested on, defined once. The `uv run --with` in the pane
// script uses it; codex_view.py's inline header repeats it because a script header cannot
// import, and register.test.ts fails if the two differ.
export const TEXTUAL_REQ = 'textual>=8.2,<9'

// Chained calls (isStandalone in tools.ts) capture the whole original command's
// stdout and stderr into orig.out and orig.err while the same streams still feed the
// pane's live log (clean.log), by two tees. The command's own status goes through
// orig.st, since a pipeline reports the last stage.
const RUN_ORIG = [
  'run_orig() {',
  '  { { "$@" 2>&1 1>&3 3>&-; echo $? > "$D/orig.st"; } | tee "$D/orig.err" >(mdrest >> "$D/clean.md") | restfilter "${MCP_SEEN_LOG:-}" >> "$D/clean.log"; } 3>&1 | tee "$D/orig.out" >(mdrest >> "$D/clean.md") | restfilter "${MCP_SEEN_LOG:-}" >> "$D/clean.log"',
  '  return "$(cat "$D/orig.st")"',
  '}',
]

// After a chained run: rest.out / rest.err are orig.out / orig.err put through the same
// noise rules as clean.md (restfilter, mdpipe.ts); the report returns them. The
// unfiltered streams stay in orig.out / orig.err.
const MKREST = 'mkrest() { for s in out err; do restfilter "$D/mcp.ret.seen" < "$D/orig.$s" > "$D/rest.$s"; done; }'

const USAGE = [
  '  jq -R -r --arg mode usage -f "$ROOT/viewer/codex.jq" "$D/raw.log" 2>/dev/null | tail -n 1 > "$D/usage"',
  '  [ -s "$D/usage" ] || { k=$(grep -A1 "^tokens used" "$D/clean.log" 2>/dev/null | tail -1); [ -n "$k" ] && echo "$k tokens" > "$D/usage"; }',
  '  echo "$X" > "$D/exit.tmp"; date +%s > "$D/end"; mv "$D/exit.tmp" "$D/exit"',
]

// The background half of the pane for codex. Codex's output (JSONL for exec, plain
// text for review, stderr merged) goes to raw.log untouched, then through codex.jq
// (events become text, other lines pass) and clean.awk (noise rules) into clean.log.
// A second consumer of the same tee, mdcodex (mdpipe.ts), writes clean.md live; once the
// run ends clean.md is rebuilt whole from raw.log, which makes it complete however the
// live writer was scheduled.
// After the run, `usage` gets the token split from the same codex.jq, else the
// "tokens used" figure; the report and the viewer both read that one file.
const CODEX_RUN = [
  '  __CODEX_PROFILE="__PROFILE__" __CODEX_LAST="$D/last.md" __CODEX_REVIEW_LAST=__REVIEWLAST__ bash -c \'. "$1/shim.sh"; . "$1/orig.sh"\' _ "$D" 2>&1 \\',
  '    | tee "$D/raw.log" >(mdcodex >> "$D/clean.md") | jq --unbuffered -R -r -f "$ROOT/viewer/codex.jq" 2>/dev/null \\',
  '    | awk -v review=1 -f "$ROOT/viewer/clean.awk" > "$D/clean.log"',
  '  X="${PIPESTATUS[0]}"',
  '  mdcodex < "$D/raw.log" > "$D/clean.md.tmp" && mv "$D/clean.md.tmp" "$D/clean.md"',
  ...USAGE,
]

// Chained: the shim (shim.ts) feeds raw.log and clean.log itself and gives the
// command's stdout the answer text.
const CODEX_CHAIN_RUN = [
  '  : > "$D/raw.log"; : > "$D/clean.log"',
  '  export __CODEX_PROFILE="__PROFILE__" __CODEX_LAST="$D/last.md" __CODEX_CHAIN=1 __CODEX_D="$D" __CODEX_ROOT="$ROOT"',
  '  run_orig bash -c \'. "$1/shim.sh"; . "$1/orig.sh"\' _ "$D"; X=$?',
  '  mkrest',
  ...USAGE,
]

// For ccx: stdout (the status line and the result) goes to out.txt untouched and
// stderr to err.log. A follower finds the run's stream-json log: a *.jsonl that was not in
// the runs directory when the pane started and that no other pane has claimed (an atomic
// mkdir per log name), so two overlapping runs never follow the same log and no timestamp
// comparison is needed. A launch lock lets only one run at a time wait for its new log, so
// the log a run claims is the one it started. It renders each complete line through stream.jq (text
// into clean.log, Markdown into clean.md). It polls by line count, so a half-written line waits for its newline
// and the final pass after the command ends takes whatever is left. The Markdown is rendered
// from line 1 each time (a call and its result are paired across lines, so a chunk alone is
// not enough) and only the new bytes are appended; the final pass (mode md) also shows a
// call that never got a result.
const CCX_RUN = [
  '  RUNS="${CCX_RUNS_DIR:-}"; [ -n "$RUNS" ] || RUNS=__RUNS__; : > "$D/clean.log"',
  // One claims folder per OS user, so another user's folder in a shared /tmp cannot block this one
  '  CLAIMS="${TMPDIR:-/tmp}/codex-herdr-ccx-claims-$(id -u)"; mkdir -p -m 700 "$CLAIMS" 2>/dev/null',
  // Which log is whose: a run may claim a new log only while it holds the launch lock and no
  // other run's log is UNBOUND (a run in flight whose log could still appear). Waiters wait for
  // the lock, so nothing else launches while a claimer looks. A holder releases the lock when it
  // has claimed its log, or when CODEX_HERDR_CCX_WAIT (30 s) passes: then it marks itself unbound
  // first, so its late log is never taken. A run that finds an unbound run marks itself unbound,
  // releases the lock at once and claims nothing. A mark lasts until that run's command ends (or
  // its process is gone). A holder that died is broken by its pid.
  '  LOCK="$CLAIMS/launch.lock"; UNB="$CLAIMS/unbound"; mkdir -p "$UNB" 2>/dev/null; waited=0',
  '  note() { echo "*$1*" | tee -a "$D/clean.log" >> "$D/clean.md"; }',
  // A lock that cannot be made, and is not there, is not contention: the folder is not usable, so
  // the run claims nothing (OK=0). Only one run at a time may break a dead holder's lock (the
  // .break folder), and it checks the pid again first, so it never deletes a successor's lock.
  '  OK=1; r=0; [ -d "$CLAIMS" ] && [ -w "$CLAIMS" ] || OK=0',
  '  while [ "$OK" = 1 ] && ! mkdir "$LOCK" 2>/dev/null; do',
  // the lock was released between the mkdir and this check: try again (a few times, then give up)
  '    [ -d "$LOCK" ] || { r=$((r+1)); [ "$r" -lt 50 ] && continue; OK=0; break; }',
  '    p=$(cat "$LOCK/pid" 2>/dev/null)',
  '    if [ -n "$p" ] && ! kill -0 "$p" 2>/dev/null && mkdir "$LOCK.break" 2>/dev/null; then',
