  '  else bash "$D/orig.sh" > "$D/out.txt" 2> "$D/err.log"; X=$?; fi',
  '  cat "$D/err.log" > "$D/raw.log"',
  '  touch "$D/cmddone"; wait $FOLLOW; release; rm -f "$UNB/$$"',
