// Splits a run's clean.md into prose and folds for the Claude Code pane (runpane.tsx): the same
// rules as viewer/codex_view.py's LiveDoc. A fold is a tool result between the markers md.jq
// writes; a marker counts only outside a fenced block (CommonMark fences, as md.jq's
// fence_open / fence_step), so tool output and prose cannot make one.

export type RunPart =
  | { kind: 'prose'; text: string }
  | { kind: 'fold'; title: string; body: string; failed: boolean }

type Fence = { c: string; n: number } | null

const FOLD_OPEN = /^<!-- fold (open|closed): (.*) -->$/
const FOLD_END = '<!-- /fold -->'
const FENCE_OPEN = /^ {0,3}(`{3,}|~{3,})(.*)$/
// The call's label (md.jq's toolline), the first line of a fold body
const LABEL = /^\*\*[A-Za-z0-9_.:-]+\*\*( .*)?$/

export function fenceStep(state: Fence, line: string): Fence {
  if (state === null) {
    const m = FENCE_OPEN.exec(line)
    if (m && (m[1]![0] === '~' || !m[2]!.includes('`'))) return { c: m[1]![0]!, n: m[1]!.length }
    return null
  }
  const close = new RegExp(`^ {0,3}${state.c === '`' ? '`' : '~'}{${state.n},}\\s*$`)
  return close.test(line) ? null : state
}

// The fold's Markdown without the label that repeats its title; a cut title ("...") keeps it,
// the only place the whole command is shown.
function foldBody(title: string, lines: string[]): string {
  const rest = lines.length > 0 && !title.includes('...') && LABEL.test(lines[0]!) ? lines.slice(1) : lines
  return rest.join('\n').replace(/^\n+|\n+$/g, '') || '*(empty)*'
}

// Only complete lines are read (a trailing partial line waits for its newline). A fold whose end
// marker has not arrived is held back, unless `final` (the run ended): then it is shown as is.
export function parseRun(text: string, final = false): RunPart[] {
  const end = text.lastIndexOf('\n')
  const lines = (final ? text : text.slice(0, end + 1)).split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const parts: RunPart[] = []
  let prose: string[] = []
  let fence: Fence = null
  let fold: { title: string; failed: boolean; lines: string[]; fence: Fence } | null = null
  const flush = () => {
    if (prose.join('').trim()) parts.push({ kind: 'prose', text: prose.join('\n').replace(/\n+$/, '') })
    prose = []
  }
  for (const line of lines) {
    if (fold) {
      if (fold.fence === null && line === FOLD_END) {
        parts.push({ kind: 'fold', title: fold.title, failed: fold.failed, body: foldBody(fold.title, fold.lines) })
        fold = null
      } else {
        fold.lines.push(line)
        fold.fence = fenceStep(fold.fence, line)
      }
      continue
    }
    const m = fence === null ? FOLD_OPEN.exec(line) : null
    if (m) {
      flush()
      fold = { title: m[2]!, failed: m[1] === 'open', lines: [], fence: null }
      continue
    }
    prose.push(line)
    fence = fenceStep(fence, line)
  }
  flush()
  if (fold && final) parts.push({ kind: 'fold', title: fold.title, failed: fold.failed, body: foldBody(fold.title, fold.lines) })
  return parts
}

// The run as plain text, for /codex-runs where no surface draws panes (the reply lands in the
// chat): the assistant's text, one line per tool result (a failed one with the first lines of its
// output), then the answer. Headings and fences are dropped so it reads as text; the newest part
// is kept when it is long.
const FAILED_LINES = 6
const MAX_SUMMARY = 6000

function plainLines(md: string): string[] {
  // headings, fences, the thinking label and codex's token footer (the head already says it)
  return md.split('\n').filter((l) => !/^#{1,6} /.test(l) && !/^ {0,3}(`{3,}|~{3,})/.test(l) && l !== '**thinking**' && !/^\*input [0-9,]+ .*\*$/.test(l))
}

export function summarizeRun(parts: RunPart[], head: string, answer: string, logPath: string): string {
  const body: string[] = []
  for (const p of parts) {
    if (p.kind === 'prose') {
      const text = plainLines(p.text).join('\n').replace(/\n{3,}/g, '\n\n').trim()
      if (text) body.push(...(body.length ? [''] : []), text, '')
      continue
    }
    body.push(`${p.failed ? '✗' : '✓'} ${p.title}`)
    if (p.failed) {
      const out = plainLines(p.body).filter((l) => l.trim() && !l.startsWith('> **error**') && !/^\*\*[A-Za-z0-9_.:-]+\*\*/.test(l))
      body.push(...out.slice(0, FAILED_LINES).map((l) => `    ${l}`))
      if (out.length > FAILED_LINES) body.push(`    ... ${out.length - FAILED_LINES} more lines`)
    }
  }
  let text = body.join('\n').replace(/\n{3,}/g, '\n\n').trim()
  if (text.length > MAX_SUMMARY) text = '... (earlier steps cut)\n' + text.slice(-MAX_SUMMARY)
  const tail = answer.trim() ? `\n\n--- answer ---\n${answer.trim()}` : ''
  return `${head}\n\n${text || '(no events yet)'}${tail}\n\nFull log: ${logPath}`
}

files.hooks/runview.tsx:
// Draws one run's Claude Code pane (runpane.tsx's ui.render hook): a header, the Live / Answer /
// Open-all buttons, then Live (prose, and each tool result as a fold: a Button row that opens it)
// or Answer. The log is read from clean.md here, its tail only once it is long, so the state never
// holds it.

import type { EngineInterface as Api } from 'claude-code'
import type { RunView } from '../types'
import { parseRun, type RunPart } from './livedoc.ts'
import { patch, runStatus, text } from './runstate.ts'

type Fold = Extract<RunPart, { kind: 'fold' }>
type Ui = ReturnType<Api['ui']['resolve']>

export const MAX_CHARS = 80000 // what one drawing shows (the engine cuts a drawing at 100000)
const TAIL_CHARS = 400000 // of a longer log only this much is read into a drawing

// The log's parts, from a top-level boundary (a fold or a heading) when only its tail is read
export async function loadParts($: Api, r: RunView): Promise<{ parts: RunPart[]; cut: boolean }> {
  let md = (await text($, `${r.dir}/clean.md`)) ?? ''
  const cut = md.length > TAIL_CHARS
  if (cut) {
    const tail = md.slice(-TAIL_CHARS)
    const at = tail.search(/\n(<!-- fold (open|closed): |#{1,6} )/)
    md = at >= 0 ? tail.slice(at + 1) : tail.slice(tail.indexOf('\n') + 1)
  }
  return { parts: parseRun(md, r.exit !== undefined), cut }
}

// The newest parts that fit MAX_CHARS. The newest alone may not: then it is cut to its last
// MAX_CHARS characters (a fold's body; prose from a line start).
export function fitParts(parts: RunPart[], isOpen: (i: number, p: Fold) => boolean) {
  let room = MAX_CHARS, first = parts.length
  const shown = parts.slice()
  while (first > 0) {
    const i = first - 1, p = shown[i]!
    const cost = p.kind === 'prose' ? p.text.length : p.title.length + (isOpen(i, p) ? p.body.length : 0)
    if (cost > room && first < parts.length) break
    if (cost > room) shown[i] = clip(p, room)
    room -= Math.min(cost, room); first = i
  }
  return { first, shown: shown.slice(first) }
}

function clip(p: RunPart, room: number): RunPart {
  const keep = Math.max(0, room - 200)
  const cutText = (t: string) => { const s = t.slice(-keep); return `*... earlier text cut*\n\n${s.slice(s.indexOf('\n') + 1)}` }
  return p.kind === 'prose' ? { ...p, text: cutText(p.text) } : { ...p, body: cutText(p.body) }
}

function foldRow(ui: Ui, $: Api, r: RunView, i: number, p: Fold, open: boolean) {
  const { Box, Button, Markdown, Text } = ui
  const toggle = () => void patch($, r.id, (c) => ({ ...c, open: { ...c.open, [String(i)]: !open } }))
  return (
    <Box key={`f${i}`} flexDirection="column">
      <Button key={`fold-${i}`} plain onPress={toggle}>
        {open ? '▼ ' : '▶ '}<Text color={p.failed ? 'red' : undefined}>{p.title}</Text>
      </Button>
      {open && <Box paddingLeft={2}><Markdown key={`b${i}`} text={p.body} /></Box>}
    </Box>
  )
}

function buttons(ui: Ui, $: Api, r: RunView, folds: number[], allOpen: boolean) {
  const { Box, Button } = ui
  const setTab = (tab: RunView['tab']) => void patch($, r.id, (c) => ({ ...c, tab }))
  const setAll = () => void patch($, r.id, (c) => ({ ...c, open: Object.fromEntries(folds.map((i) => [String(i), !allOpen])) }))
  return (
    <Box flexDirection="row" gap={1}>
      <Button key="tab-live" hotkey="l" variant={r.tab === 'live' ? 'primary' : undefined} onPress={() => setTab('live')}>Live</Button>
      <Button key="tab-answer" hotkey="a" variant={r.tab === 'answer' ? 'primary' : undefined} onPress={() => setTab('answer')}>Answer</Button>
      {r.tab === 'live' && folds.length > 0 && <Button key="folds" hotkey="f" onPress={setAll}>{allOpen ? 'Close all' : 'Open all'}</Button>}
    </Box>
  )
}

function liveView(ui: Ui, $: Api, r: RunView, parts: RunPart[], cut: boolean) {
  const { Box, Markdown, Text } = ui
  const isOpen = (i: number, p: Fold) => r.open[String(i)] ?? p.failed
  const { first, shown } = fitParts(parts, isOpen)
  const rows = shown.map((p, k) => {
    const i = first + k
    return p.kind === 'prose' ? <Markdown key={`p${i}`} text={p.text} /> : foldRow(ui, $, r, i, p, isOpen(i, p))
  })
  return (
    <Box flexDirection="column" gap={1}>
      {(first > 0 || cut) && <Text dimColor>Earlier entries not shown: {r.dir}/clean.md</Text>}
      {parts.length === 0 && <Text dimColor>Waiting for the first event...</Text>}
      {rows}
    </Box>
  )
}

export async function renderPane(ui: Ui, $: Api, r: RunView, now: number) {
  const { Box, Markdown, Text } = ui
  const ok = r.exit === '0'
  const { parts, cut } = r.tab === 'live' ? await loadParts($, r) : { parts: [] as RunPart[], cut: false }
  const folds = parts.flatMap((p, i) => (p.kind === 'fold' ? [i] : []))
  const allOpen = folds.length > 0 && folds.every((i) => r.open[String(i)] ?? (parts[i] as Fold).failed)
  const answer = r.answer || (r.exit === undefined ? '*The answer appears here when the run finishes.*' : '*No answer was written; see Live.*')
  return (
    <Box flexDirection="column" gap={1}>
      <Box flexDirection="column">
        <Text bold>{r.label}</Text>
        <Text color={r.exit === undefined ? undefined : ok ? 'green' : 'red'} dimColor={r.exit === undefined}>{runStatus(r, now)}</Text>
      </Box>
      {buttons(ui, $, r, folds, allOpen)}
      {r.tab === 'answer' ? <Markdown key="answer" text={answer} /> : liveView(ui, $, r, parts, cut)}
    </Box>
  )
}

files.hooks/runhtml.ts:
// A finished run as one HTML page (run.html beside the run's logs): the answer first, then the
// run with each tool result in a <details> fold (closed when it passed, open when it failed).
// For surfaces that draw no mod panes: Claude sends the page to the person as a file. Everything
// taken from the run is escaped; the Markdown is a small subset (headings, fences, quotes, lists,
// bold, italic and inline code), enough for what codex.jq, stream.jq and an answer write.

import { fenceStep, type RunPart } from './livedoc.ts'

export type RunPageInput = {
  label: string
  status: string // "finished in 22s · input ..." as runpane.tsx says it
  ok: boolean
  parts: RunPart[]
  answer: string
  logPath: string
}

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

// Code spans are cut out first, so `*` and `**` inside them stay as written
const emphasis = (t: string) => esc(t)
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  .replace(/(^|[^*])\*([^*\s][^*]*)\*/g, '$1<em>$2</em>')
// A code span opens and closes on backtick runs of the same length (CommonMark)
const CODE_SPAN = /(`+)(?!`)([\s\S]*?[^`])\1(?!`)/g
function inline(t: string): string {
  let out = '', at = 0
  for (const m of t.matchAll(CODE_SPAN)) {
    out += emphasis(t.slice(at, m.index)) + `<code>${esc(m[2]!.trim() || m[2]!)}</code>`
    at = m.index! + m[0].length
  }
  return out + emphasis(t.slice(at))
}

export function mdToHtml(src: string): string {
  const lines = src.replace(/\r/g, '').split('\n')
  const out: string[] = []
  let i = 0
  while (i < lines.length) {
    const l = lines[i]!
    // the fence rule of livedoc.ts (CommonMark's), so the page and the pane agree on every block
    let fence = fenceStep(null, l)
    if (fence) {
      const body: string[] = []
      for (i++; i < lines.length && (fence = fenceStep(fence, lines[i]!)) !== null; i++) body.push(lines[i]!)
      i++
      out.push(`<pre>${esc(body.join('\n'))}</pre>`)
      continue
    }
    const h = /^(#{1,6}) (.*)$/.exec(l)
    if (h) {
      if (h[2] !== 'Turn') out.push(`<h3>${inline(h[2]!)}</h3>`) // codex.jq's turn marker says nothing on a page
      i++
      continue
    }
    if (l.startsWith('> ')) { out.push(`<blockquote>${inline(l.slice(2))}</blockquote>`); i++; continue }
    if (/^[-*] /.test(l)) {
      const items: string[] = []
      while (i < lines.length && /^[-*] /.test(lines[i]!)) items.push(`<li>${inline(lines[i++]!.slice(2))}</li>`)
      out.push(`<ul>${items.join('')}</ul>`)
      continue
    }
    if (!l.trim()) { i++; continue }
    const para: string[] = []
    while (i < lines.length && lines[i]!.trim() && !fenceStep(null, lines[i]!) && !/^(#{1,6} |> |[-*] )/.test(lines[i]!)) para.push(lines[i++]!)
    out.push(`<p>${inline(para.join(' '))}</p>`)
  }
  return out.join('\n')
}

const CSS = `:root{--bg:#fbfaf7;--fg:#1f1f1c;--muted:#6b6a64;--line:#e4e1d8;--card:#fff;--ok:#2f7d4f;--bad:#b3362b;--code:#f3f1ea}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#171715;--fg:#ecebe6;--muted:#a09e96;--line:#34332f;--card:#1f1f1c;--ok:#6cc08b;--bad:#ef7b6f;--code:#262622}}
:root[data-theme="dark"]{--bg:#171715;--fg:#ecebe6;--muted:#a09e96;--line:#34332f;--card:#1f1f1c;--ok:#6cc08b;--bad:#ef7b6f;--code:#262622}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.55 ui-sans-serif,system-ui,-apple-system,sans-serif}
main{max-width:860px;margin:0 auto;padding:24px 16px 48px}
header{border-left:4px solid var(--state);padding:4px 0 4px 14px;margin-bottom:20px}
header h1{font-size:18px;margin:0 0 2px;overflow-wrap:anywhere}header p{margin:0;color:var(--muted);font-size:13px}
.tabs{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 16px}.tabs button{font:inherit;border:1px solid var(--line);background:var(--card);color:var(--fg);padding:5px 12px;border-radius:6px;cursor:pointer}
.tabs button[aria-pressed="true"]{border-color:var(--fg);font-weight:600}
h3{font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);margin:18px 0 6px}
pre{background:var(--code);padding:10px 12px;border-radius:6px;overflow-x:auto;font:13px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;margin:8px 0}
code{background:var(--code);padding:1px 4px;border-radius:4px;font-size:.92em}
blockquote{margin:8px 0;padding:4px 10px;border-left:3px solid var(--bad);color:var(--bad)}
details{border:1px solid var(--line);background:var(--card);border-radius:8px;margin:8px 0;padding:0 12px}
details>summary{cursor:pointer;padding:8px 0;font:13px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}
details.failed{border-color:var(--bad)}details.failed>summary{color:var(--bad)}
details[open]>summary{border-bottom:1px solid var(--line);margin-bottom:6px}
.answer{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:4px 16px}
.hidden{display:none}footer{margin-top:24px;color:var(--muted);font-size:12px;overflow-wrap:anywhere}`

const SCRIPT = `const show=t=>{for(const n of['live','answer']){document.getElementById(n).classList.toggle('hidden',n!==t);document.getElementById('t-'+n).setAttribute('aria-pressed',String(n===t))}document.getElementById('t-all').classList.toggle('hidden',t!=='live')};
document.getElementById('t-live').onclick=()=>show('live');document.getElementById('t-answer').onclick=()=>show('answer');
document.getElementById('t-all').onclick=e=>{const f=[...document.querySelectorAll('details')];const open=f.some(d=>!d.open);f.forEach(d=>d.open=open);e.target.textContent=open?'Close all':'Open all'};
show(document.body.dataset.first);`

export function runPage(p: RunPageInput): string {
  const live = p.parts.map((part) => part.kind === 'prose'
    ? `<section>${mdToHtml(part.text)}</section>`
    : `<details${part.failed ? ' class="failed" open' : ''}><summary>${esc(part.title)}</summary>${mdToHtml(part.body)}</details>`).join('\n')
  const answer = p.answer.trim() ? mdToHtml(p.answer) : '<p><em>No answer was written; see Live.</em></p>'
  const first = p.ok && p.answer.trim() ? 'answer' : 'live'
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Delegation Run</title><style>${CSS}</style></head>
<body data-first="${first}" style="--state:var(${p.ok ? '--ok' : '--bad'})"><main>
<header><h1>${esc(p.label)}</h1><p>${esc(p.status)}</p></header>
<div class="tabs"><button id="t-live" aria-pressed="false">Live</button><button id="t-answer" aria-pressed="false">Answer</button><button id="t-all">Open all</button></div>
<div id="live">${live || '<p><em>No events were logged.</em></p>'}</div>
<div id="answer" class="answer">${answer}</div>
<footer>Full log: ${esc(p.logPath)}</footer>
<script>${SCRIPT}</script></main></body></html>
`
}

